import os 
from pathlib import Path 
import fitz
import shutil 
from google.clound import storage
from dataclasses import dataclass 

@dataclass
class Book : 
    book_id : str 
    bucket : str 
    object_name : str
    filename : str  


class PDFRenderer : 
    def __init__(self ,source_bucket : str , artefact_bucket : str , dpi : int = 300) -> None : 
        self.client =  storage.Client()
        self.processing_bucket = self.client.bucket(source_bucket)
        self.artefact_bucket = self.client.bucket(artefact_bucket)
        self.dpi = dpi
        self.temp_dir = Path("temp")
        self.temp_dir.mkdir(parents=True , exist_ok=True)
    
    def render(self , book_id : str) ->dict :
        pdf_blob = self.processing_bucket.blob(f"books/{self.book_id}/source.pdf")
        local_pdf = self.temp_dir / f"source.pdf"
        pdf_blob.download_to_filename(local_pdf)
        document = fitz.open(local_pdf)
        zoom = self.dpi / 72  # 72 dpi is the default resolution
        mat = fitz.Matrix(zoom, zoom)
        pages = []
        
        for i in range(len(document)) : 
            page = document.load_page(i)
            pixmap = page.get_pixmap(matrix=mat)
            local_image = (
                self.temp_dir / f"page_{i+1:04}.png"
            )
            pixmap.save(local_image)
            destination = ( 
                           f"books/{book_id}/"
                           f"rendered/"
                           f"page_{i+1:04}.png")
            
            blob = self.artefact_bucket.blob(destination)
            blob.upload_from_filename(local_image)
            pages.append(destination)
            print(f"Uploaded page {i+1} to {destination}")
        
        document.close()
        shutil.rmtree(self.temp_dir)
        return { 
                "book_id": book_id,
                "pages_renedered" : len(pages),
            "pages": pages
        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
        